Section DIG.
  Context {HCEIL : HeapCeil}.

Definition ADIG_STACK : Z := 16.

Definition dig_post_v (v : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (bv_swrap 32 v)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ bytes_at asegs m' P bs
    /\ ACONST m' /\ accessible m' P (Z.of_nat (length bs)).

Definition digest_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  dig_post_v (ft_digest (zbytes bs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m.

Definition digest_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P lo : Z) (bs : list byte),
  bytes_at asegs m P bs -> P + Z.of_nat (length bs) < 2^64 ->
  stk asegs m lo (bv_unsigned sp) -> lo + ADIG_STACK <= bv_unsigned sp -> aceil <= lo ->      (* [comment removed for export] *)
  (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo) ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  ACONST m -> accessible m P (Z.of_nat (length bs)) ->
  evt asegs (digest_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz (Z.of_nat (length bs))) a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELD_TABLE_DIGEST) fc None m (seg_rom asegs)).

(* [comment removed for export] *)
Definition dg_side (m : mem) (P n : Z) : Prop := ACONST m /\ accessible m P n.
Lemma dg_side_now : forall m m1 P n lo hi,
  dg_side m P n -> munch [(lo, hi)]%Z m m1 -> wmono asegs m m1 -> aceil <= lo -> dg_side m1 P n.
Proof.
  intros m m1 P n lo hi (AC & AW) MU WM CEIL.
  assert (FW : Forall awin [(lo, hi)]%Z) by (apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_nil]).
  split; [eapply aconst_transport_awin; eassumption| eapply acc_transport_awin; eassumption].
Qed.

Definition dig_ctx (m m1 : mem) (sp rav : word) (j8 : list byte) (P lo : Z) (bs : list byte) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -16) [CB 8 j8; C8 rav]
  /\ bytes_at asegs m1 P bs
  /\ stk asegs m1 lo (bv_unsigned sp + -16)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ dg_side m P (Z.of_nat (length bs)).

Definition dig_pure (sp : word) (P lo : Z) (bs : list byte) : Prop :=
  P + Z.of_nat (length bs) < 2^64 /\ lo + ADIG_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo).

End DIG.

Ltac dg_open CTX PURE :=
  destruct CTX as (FR & WIN & ST & MU & WM & MI & SD);
  destruct PURE as (WEND & LO & CEIL & SEPS);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof aceil_facts as (AF1 & _);
  hydeL SEPS;
  unfold ADIG_STACK in *.

(* [comment removed for export] *)
Ltac dg_bchk_gen SD MU WM CEIL a PRE MID JOIN :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let AP := fresh "AP" in let v := fresh "v" in let V1 := fresh "V1" in let V2 := fresh "V2" in let RD := fresh "RD" in
    let w := fresh "w" in
    destruct (dg_side_now _ mc _ _ _ _ SD MU WM CEIL) as (_ & AP);
    destruct (accessible_readw_sr mc a 1 (accessible_sub _ _ _ a 1 AP ltac:(lia) ltac:(lia) ltac:(lia)) ltac:(lia)
                ltac:(clear; Z.div_mod_to_equations; lia)) as (v & V1 & V2 & RD);
    clear AP;
    PRE; clear RD;
    first [ rewrite (sxb_b8_small v) by (clear - V1; lia) | rewrite (zxb_b8_small v) by (clear - V1; lia) ];
    MID;
    JOIN V1 V2; intros w; clear V1 V2
  end.
Ltac dg_join_ge V1 V2 := shchk_join_ge V1 V2.
Ltac dg_join_lt V1 V2 := shchk_join V1 V2.
Ltac dg_bchk_ge SD MU WM CEIL a PRE MID := dg_bchk_gen SD MU WM CEIL a PRE MID dg_join_ge.
Ltac dg_bchk_lt SD MU WM CEIL a PRE MID := dg_bchk_gen SD MU WM CEIL a PRE MID dg_join_lt.

