    (F : bvmap 5 word) fc (m m1 : mem) (P lo : Z) (bs : list byte) (r : Z),
  (length bs - j <= k)%nat -> (j + 4 <= length bs)%nat -> 0 <= r < 2^32 ->
  dig_ctx m m1 sp ra j8 P lo bs -> dig_pure sp P lo bs ->
  evt asegs (dig_post_v (ft_digest_from r (zbytes (skipn j bs))) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m)
